def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_re = re.compile(r"[0-9]+|[A-Z]+[0-9]*|<>|<=|>=|[()+*/,:=<>-]")
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def integer(text):
        negative = text.startswith("-")
        digits = text.lstrip("+-")
        value = 0
        for i in range(0, len(digits), 1000):
            chunk = digits[i:i + 1000]
            value = value * (10 ** len(chunk)) + int(chunk)
        return -value if negative else value

    def parse(formula):
        operands = []
        operators = []
        pending_function = None
        expecting_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                operands.append(("neg", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append((op, left, right))

        for match in token_re.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                operands.append(integer(token))
                expecting_operand = False

            elif token in functions:
                pending_function = token

            elif token[0].isalpha():
                operands.append(token)
                expecting_operand = False

            elif token == "(":
                operators.append([pending_function, 1])
                pending_function = None
                expecting_operand = True

            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                operators[-1][1] += 1
                expecting_operand = True

            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                function, count = operators.pop()
                if function is not None:
                    arguments = operands[-count:]
                    del operands[-count:]
                    operands.append((function, arguments))
                expecting_operand = False

            else:
                op = "neg" if token == "-" and expecting_operand else token
                while operators and isinstance(operators[-1], str):
                    previous = operators[-1]
                    if precedence[previous] < precedence[op]:
                        break
                    if previous == op == "neg":
                        break
                    reduce_operator()
                operators.append(op)
                expecting_operand = True

        while operators:
            reduce_operator()
        return operands[0]

    def expand_arguments(arguments):
        for argument in arguments:
            if isinstance(argument, tuple) and argument[0] == ":":
                first, last = argument[1], argument[2]
                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                row1, row2 = sorted((int(first[1:]), int(last[1:])))
                for row in range(row1, row2 + 1):
                    for col in range(col1, col2 + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield name
            else:
                yield argument

    values = {}
    active = set()

    def evaluate(expression):
        if isinstance(expression, int):
            return expression

        if isinstance(expression, str):
            name = expression
            if name not in cells:
                return 0
            if name in values:
                return values[name]
            if name in active:
                return "#CYCLE!"

            active.add(name)
            content = cells[name]
            tree = parse(content[1:]) if content.startswith("=") else integer(content)
            result = yield tree
            active.remove(name)
            values[name] = result
            return result

        op = expression[0]

        if op == "neg":
            value = yield expression[1]
            return value if isinstance(value, str) else -value

        if op == "IF":
            arguments = expression[1]
            condition = yield arguments[0]
            if isinstance(condition, str):
                return condition
            result = yield arguments[1] if condition else arguments[2]
            return result

        if op in {"SUM", "MIN", "MAX"}:
            result = 0 if op == "SUM" else None
            for argument in expand_arguments(expression[1]):
                value = yield argument
                if isinstance(value, str):
                    return value
                if op == "SUM":
                    result += value
                elif result is None:
                    result = value
                elif op == "MIN":
                    result = min(result, value)
                else:
                    result = max(result, value)
            return 0 if result is None else result

        left = yield expression[1]
        if isinstance(left, str):
            return left

        right = yield expression[2]
        if isinstance(right, str):
            return right

        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right

    # Drive generators explicitly so reference chains and nested expressions
    # do not consume Python's recursion stack.
    for name in cells:
        if name in values:
            continue

        stack = [evaluate(name)]
        result = None
        while stack:
            try:
                request = stack[-1].send(result)
            except StopIteration as finished:
                stack.pop()
                result = finished.value
            else:
                stack.append(evaluate(request))
                result = None

    return {name: values[name] for name in cells}
